import os
from pathlib import Path
import shutil
import setuptools
from setuptools.command.build_py import build_py


class BuildPyWithSkills(build_py):
    """Bundle consumer skills and their references from the canonical sources."""

    def run(self):
        super().run()
        root = Path(__file__).resolve().parent
        build_root = Path(self.build_lib).resolve()
        destination = build_root / 'Mon' / 'agent_resources'
        if destination.exists():
            # This directory is generated by this command. Rebuild it so skills
            # removed from the consumer catalog cannot survive incremental builds.
            if destination.is_symlink() or not destination.resolve().is_relative_to(build_root):
                raise ValueError('Bundled agent resources must stay inside the build directory')
            shutil.rmtree(destination)
        # Retain the repository layout so relative skill links still resolve.
        shutil.copytree(root / '.agents/skills', destination / '.agents/skills',
                        dirs_exist_ok=True, ignore=shutil.ignore_patterns('__pycache__', '*.pyc'))
        for relative in ('docs/mcp.md', 'docs/agent-setup.md', 'docs/feature-crops.md',
                         'examples/mcp_observe.py'):
            target = destination / relative
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(root / relative, target)

os.environ["PYTHONIOENCODING"] = "utf-8"

# This fork is consumed through a git URL (pip installs the tagged source), so
# the build must be self-contained. The upstream setup.py queried PyPI at build
# time to derive the next version, which needs network access and expects a
# published "ok-script" distribution to exist. Pin the version matching the tag
# instead; set MON_SCRIPT_BUILD_VERSION to override it.
VERSION_NUM = os.environ.get('MON_SCRIPT_BUILD_VERSION') or '3.0.5b8'
print(f'building Mon-script version {VERSION_NUM}')

setuptools.setup(version=VERSION_NUM, cmdclass={'build_py': BuildPyWithSkills})
